const output = $input.item.json.output || '';
const transferKeywords = ['transferir', 'equipe de reservas', 'finalizar', 'um momento', 'agendar', 'marcar', 'consulta', 'horário', 'agenda'];
const isTransferring = transferKeywords.some(keyword => output.toLowerCase().includes(keyword.toLowerCase()));
const telefone = $('Settings v3').item.json.telefone || $('Dados').item.json.Numero || '';
return [{ ...($input.item.json), shouldTransfer: isTransferring, telefone: telefone }];
